import json

SCHEMA = {"brand": str, "volume_ml": int, "count": int}


def check(raw):
    try:
        d = json.loads(raw)
    except json.JSONDecodeError:
        return "JSON 아님 -> 다시 요청"
    for k, t in SCHEMA.items():
        if k not in d:
            return f"'{k}' 빠짐 -> 다시 요청"
        if not isinstance(d[k], t):
            return f"'{k}' 형식 틀림({type(d[k]).__name__}) -> 룰로 보정"
    return f"통과 {d}"


outs = [
    '{"brand": "삼다수", "volume_ml": 2000, "count": 6}',
    '{"brand": "삼다수", "volume_ml": "2L", "count": 6}',
    '{"brand": "삼다수", "count": 6}',
    '네, 삼다수 2L 6개입입니다.',
]
for o in outs:
    print(check(o))
# 통과 {'brand': '삼다수', 'volume_ml': 2000, 'count': 6}
# 'volume_ml' 형식 틀림(str) -> 룰로 보정
# 'volume_ml' 빠짐 -> 다시 요청
# JSON 아님 -> 다시 요청

import re

# 생성한 상품명 속 숫자+단위가 원본 속성에 있는가 (가상 값)
attrs = {"브랜드": "삼다수", "용량": "2L", "수량": "6개입"}
src = " ".join(attrs.values()).lower()

def units(text):
    return re.findall(r"\d+(?:\.\d+)?\s*(?:ml|l|g|kg|개입|개|병)", text.lower())

for title in ["제주 삼다수 2L 6개입", "삼다수 2L 12개입 대용량", "삼다수 생수 묶음"]:
    bad = [u for u in units(title) if u.replace(" ", "") not in src.replace(" ", "")]
    print(title, "->", "근거 없는 값 " + str(bad) if bad else "통과")
# 제주 삼다수 2L 6개입 -> 통과
# 삼다수 2L 12개입 대용량 -> 근거 없는 값 ['12개입']
# 삼다수 생수 묶음 -> 통과

from math import log2

# 검색어 '삼다수 2l' 결과 5개에 사람이 매긴 관련도(2 정확·1 부분·0 무관), 가상 값
def dcg(rels):
    return sum((2**r - 1) / log2(i + 2) for i, r in enumerate(rels))

ideal = [2, 2, 1, 1, 0]
for name, rels in [("A 랭킹", [2, 1, 2, 0, 1]), ("B 랭킹", [0, 2, 2, 1, 1])]:
    print(name, f"nDCG@5 {dcg(rels) / dcg(ideal):.3f}")
# A 랭킹 nDCG@5 0.948
# B 랭킹 nDCG@5 0.723
